VALUES ('xue-r1', '谷', ARRAY[]::text[], '任', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '春秋薛国国君，任姓，名谷，谥献公。在位始年不详。《左传·昭公三十一年》载夏四月丁巳薛伯谷卒，秋葬薛献公（前511年）。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/薛献公"},{"label":"《左传·昭公三十一年》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/昭公#昭公三十一年"},{"label":"《春秋滕薛杞越莒邾許七國統表》卷三（引《左传》杜注、孔疏）","url":"https://www.shidianguji.com/zh/book/CADAL02030731/chapter/1l6u63jtnvzfq"}]'::jsonb, '献公', NULL, '薛献公')
