VALUES ('xue-r2', '定', ARRAY[]::text[], '任', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '薛襄公，薛国君主。在薛（前510年—前498年）在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/薛襄公"}]'::jsonb, '襄公', NULL, '薛襄公')
