VALUES ('xue-r4', '夷', ARRAY[]::text[], '任', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '是春秋时代薛国国君，任姓，伯爵，名夷。鲁定公十三年（前497年），薛国人弑杀薛公比，拥立公子夷为君。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/薛惠公"}]'::jsonb, '惠公', NULL, '薛惠公')
