VALUES ('teng-r0', '绣', ARRAY[]::text[], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '周武王所封的滕国始封君。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕错叔"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]'::jsonb, NULL, NULL, '错叔')
