VALUES ('teng-r20', '？', ARRAY[]::text[], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '错叔绣之后的早期滕君，处于西周成康之际。金文称滕伯、滕公，为康王时期滕侯的前任；本名与具体在位年失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕公"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]'::jsonb, NULL, NULL, '公')
