INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('teng-r21', '？', ARRAY[]::text[], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '西周康王时期的滕君，《滕侯方鼎》与《滕侯簋》铭文称滕侯；《滕侯簋》为前任滕公作器。本名与具体在位年失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕侯"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]'::jsonb, NULL, NULL, '侯')
