VALUES ('teng-r22', '命仲', ARRAY[]::text[], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '《滕虎簋》铭文所载滕虎之父命仲。张志鹏据金文与亲属关系推为康昭之际的第四世滕君；具体在位年失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/命仲"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]'::jsonb, NULL, NULL, '命仲')
