VALUES ('teng-r23', '？', ARRAY[]::text[], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '命仲之子、滕伯文之父，本名失载。张志鹏据世系推为昭王时期的第五世滕君；与滕虎的关系及该世君主身份有不同考证。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕侯"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]'::jsonb, NULL, NULL, '？')
