VALUES ('teng-r24', '文', ARRAY[]::text[], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '《礼记·檀弓上》所见滕伯文，为孟虎服齐衰。张志鹏将其与金文滕虎世系联系，推为昭穆之际的第六世滕君；具体在位年失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕伯文"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《礼记·檀弓上》：滕伯文与孟虎的亲属关系","url":"https://ctext.org/text.pl?if=gb&node=9665&show=parallel"}]'::jsonb, NULL, NULL, '伯文')
