VALUES ('teng-r1', '穀', ARRAY['滕庄公','滕侯穀','姬毂'], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '《春秋》隐公七年记滕侯卒，年当-716年；即位年失考。杨甲《六经图》称庄公、名穀，陈厚耀《春秋世族谱》名毂；世次数亦有不同说法。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕庄公"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]'::jsonb, '庄公', NULL, '庄公')
