VALUES ('teng-r13', '？', ARRAY[]::text[], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '鲁隐公十一年（-712年）与薛侯朝鲁的滕侯。张志鹏考定其在位为-715至-711年；本名失考，后继滕子于-710年朝鲁。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕侯"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]'::jsonb, NULL, NULL, '侯')
