VALUES ('ju-r4', '舆', ARRAY[]::text[], '己', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '莒子舆（展舆），犂比公子，前541年在位仅一年。犂比公暴虐时先被立为太子，终短暂即位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒子舆"}]'::jsonb, NULL, NULL, '子舆')
