VALUES ('ju-r5', '去疾', ARRAY[]::text[], '己', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '莒著丘公（去疾），犂比公子，前540–前528年在位。著丘公卒后，子郊公狂与弟庚舆争立，引发内乱。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒著丘公"}]'::jsonb, '著丘公', NULL, '莒著丘公')
