VALUES ('ju-r6', '庚舆', ARRAY[]::text[], '己', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '莒共公（庚舆），犂比公子，好铸剑以人试刃，暴虐失国，前527–前519年在位。国人逐之，迎郊公狂复位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒共公"}]'::jsonb, '共公', NULL, '莒共公')
