VALUES ('ju-r7', '狂', ARRAY[]::text[], '己', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '莒郊公（狂），著丘公子，两度在位（前528年数月、前518–前481年）。柱厉叔知其不遇而去海上，后返国殉之；前481年卒。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒郊公"}]'::jsonb, '郊公', NULL, '莒郊公')
