VALUES ('teng-r16', '麇', ARRAY['滕考公','滕定公','姬麋','姬糜'], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '战国时期滕君、滕文公之父。赵岐《孟子章句》将定公对应《世本》的考公麇，名字亦作麋、糜。梁涛《孟子行年考》将其卒年考定为-324年；世子遣然友向孟子问丧礼，即位年失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕考公"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《孟子注疏》卷五：赵岐注考公／定公、元公／文公","url":"https://ctext.org/wiki.pl?chapter=372734&if=en"}]'::jsonb, '定公,考公', NULL, '定公')
