VALUES ('teng-r17', '弘', ARRAY['滕文公（战国）','滕元公','姬宏'], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '滕定公之子，战国时期滕文公。赵岐《孟子章句》对应《世本》的元公弘。为世子时赴楚，途经宋见孟子；父卒后遣然友问丧礼，后向孟子问治国之道。依梁涛、张志鹏考证，约-323至-316年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕元公"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《孟子注疏》卷五：赵岐注考公／定公、元公／文公","url":"https://ctext.org/wiki.pl?chapter=372734&if=en"},{"label":"滕文公年表（前323—前316年，与本包所采考证框架对照）","url":"https://zh.wikipedia.org/wiki/滕文公"}]'::jsonb, '文公,元公', NULL, '文公')
