VALUES ('teng-r18', '昃', ARRAY['滕侯昃'], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '滕侯昃戈、敦铭文所见滕君。器物形制被考定为战国中期，具体在位年及世次不详；另有将其对应春秋滕隐公的说法。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕侯昃"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]'::jsonb, NULL, NULL, '侯')
