VALUES ('teng-r19', '丘', ARRAY['滕公丘'], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '部分后世世系表所列的滕末君丘，所据为《通志·氏族略》滕氏条“至公邱”等文字。该条世数与灭国记载存在矛盾，其作为末君的身份及在位年代尚不能确证。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕公丘"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《通志》卷二十六·氏族略：滕氏（末君异说所据原文）","url":"https://zh.wikisource.org/wiki/通志_(四庫全書本)/卷026"}]'::jsonb, NULL, NULL, '公')
