VALUES ('teng-gong-middle', '？', ARRAY[]::text[], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '西周中期滕侯簋所追祭的前任滕公，与早期滕侯方鼎、簋所见滕公应作区别。本名、具体世次及在位年失考。', '[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]'::jsonb, NULL, NULL, '公')
