VALUES ('teng-zhong', '仲', ARRAY['滕仲'], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '滕侯𩵦盨铭文所载作器者之父滕仲，时代约属西周晚期。是否曾为滕君存在争议，具体世次与年代失考。', '[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]'::jsonb, NULL, NULL, '仲')
