VALUES ('teng-hou-su', '苏', ARRAY['滕侯𩵦','姬𩵦','滕侯苏'], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '两周之际滕侯盨的作器者，为其父滕仲作器。张志鹏释名苏，另一释法作𩵦；具体世次和在位年代失考。', '[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]'::jsonb, NULL, NULL, '侯')
