VALUES ('teng-hu', '虎', ARRAY['孟虎','滕侯虎','姬敢'], '姬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '滕虎簋的作器者，铭文称其父为公命仲。通常与《礼记·檀弓上》的孟虎相联系，是滕伯文的叔父；部分世系表将其列为第五世滕君，张志鹏则将该世君主推为伯文之父。', '[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《礼记·檀弓上》：滕伯文与孟虎的亲属关系","url":"https://ctext.org/text.pl?if=gb&node=9665&show=parallel"}]'::jsonb, NULL, NULL, '虎')
